def chain(points,r):
    return mf.Manifold.batch_boolean([rod(p,q,r,32) for p,q in zip(points,points[1:])]+[mf.Manifold.sphere(r,24).translate(p) for p in points],mf.OpType.Add)

def check_stl(path,source):
    raw=path.read_bytes();dtype=np.dtype([('n','<f4',(3,)),('v','<f4',(3,3)),('a','<u2')]);tri=np.frombuffer(raw,dtype,offset=84)['v'];v,index=np.unique(tri.reshape(-1,3),axis=0,return_inverse=True);s=mf.Manifold(mf.Mesh(v.astype(np.float32),index.reshape(-1,3).astype(np.uint32)));error=abs(s.volume()-source.volume())/max(1,abs(source.volume()));return {'status':str(s.status()),'relative_volume_error':float(error),'pass':s.status()==mf.Error.NoError and error<1e-4}

