        added=float((revised-body).volume());removed=float((body-revised).volume());meta=write(folder/'TPU_muscle.stl',revised);write(folder/'continuous_channel_wall.stl',wall);checks=check_stl(folder/'TPU_muscle.stl',revised);assert checks['pass'];wire=chain(nodes,.3);wire_hit=intersection(wire,revised);assert wire_hit<1e-6;inputs += [source/'design.json',source/'TPU_muscle.obj'];descriptor={'scope':'actual continuous-channel shaped TPU manufacturing candidate, NOT measured stiffness, cyclic stroke or moving equilibrium','muscle':fid,'parent_design':str((source/'design.json').relative_to(ROOT)),'parent_TPU_OBJ':str((source/'TPU_muscle.obj').relative_to(ROOT)),'parent_OBJ_sha256':hashlib.sha256((source/'TPU_muscle.obj').read_bytes()).hexdigest(),'tube_outer_radius_mm':1.6,'tube_inner_radius_mm':.85,'nominal_wall_mm':.75,'tube_material_components':wall_components,'full_material_components':components,'new_TPU_volume_mm3':float(revised.volume()),'material_added_to_parent_mm3':added,'parent_material_removed_by_lumen_recut_mm3':removed,'nominal_steel_intersection_mm3':wire_hit,'nominal_steel_clearance_mm_capped2':float(wire.min_gap(revised,2)),'OBJ_STL_roundtrip':checks,'basis_columns_display':d['basis_columns_display'],'coordinate_origin_display_mm':d['coordinate_origin_display_mm'],'pad_centres_display_mm':d['pad_centres_display_mm'],'wire_polyline_display_mm':d['wire_polyline_display_mm'],'baseline_short_guides_retained_as_reinforcement':True,'paper_relation':'2026 section3.1:actual continuous channel walls stifferthan sparse lattice; chosen0.75mmwall isour candidate,not recovered TableS2/S8parameter','mechanical_performance_verified':False,'frozen':False};(folder/'design.json').write_text(json.dumps(descriptor,indent=2),encoding='utf8');summaries.append(descriptor);row=rows[fid+'_TPU_muscle'];row['file']=str((folder/'TPU_muscle.obj').relative_to(ROOT));row['owner']='soft_unvalidated'
        # Actual print placement of the new body, not an assembly transform.
